import React, { useEffect, useState } from 'react';
import { FiUpload, FiX, FiTrash2, FiImage } from 'react-icons/fi';
import galleryService from '../services/galleryService';
import '../styles/Pages.css';
import { toast } from 'react-toastify';

const PastEventImageUpload = ({ event, onImageUploaded }) => {
  const [showUploadForm, setShowUploadForm] = useState(false);
  const [selectedFile, setSelectedFile] = useState(null);
  const [description, setDescription] = useState('');
  const [images, setImages] = useState([]);
  const [loading, setLoading] = useState(true);
  const [uploading, setUploading] = useState(false);

  useEffect(() => {
    fetchImages();
  }, [event._id]);

  const fetchImages = async () => {
    setLoading(true);
    try {
      const data = await galleryService.getGalleryByEvent(event._id);
      setImages(data);
    } catch (error) {
      console.error('Error fetching images:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleFileSelect = (e) => {
    const file = e.target.files[0];
    if (file) {
      if (file.size > 5 * 1024 * 1024) {
        toast.error('File size must be less than 5MB');
        return;
      }
      if (!file.type.startsWith('image/')) {
        toast.error('Only image files are allowed');
        return;
      }
      setSelectedFile(file);
    }
  };

  const handleUploadImage = async (e) => {
    e.preventDefault();
    if (!selectedFile) {
      toast.error('Please select an image');
      return;
    }

    setUploading(true);
    try {
      await galleryService.uploadPhotoWithDetails(event._id, selectedFile, description);
      toast.success('Image uploaded successfully!');
      setSelectedFile(null);
      setDescription('');
      setShowUploadForm(false);
      await fetchImages();
      if (onImageUploaded) {
        onImageUploaded();
      }
    } catch (error) {
      toast.error(error.response?.data?.message || 'Failed to upload image');
    } finally {
      setUploading(false);
    }
  };

  const handleDeleteImage = async (imageId) => {
    if (!window.confirm('Are you sure you want to delete this image?')) {
      return;
    }

    try {
      await galleryService.deletePhoto(imageId);
      toast.success('Image deleted successfully!');
      await fetchImages();
      if (onImageUploaded) {
        onImageUploaded();
      }
    } catch (error) {
      toast.error('Failed to delete image');
    }
  };

  return (
    <div className="past-event-image-upload">
      <div className="upload-section-header">
        <h3>
          <FiImage size={20} />
          Event Gallery
        </h3>
        {!showUploadForm && (
          <button
            className="btn-upload-trigger"
            onClick={() => setShowUploadForm(true)}
          >
            <FiUpload size={18} />
            Upload Image
          </button>
        )}
      </div>

      {/* Upload Form */}
      {showUploadForm && (
        <div className="upload-form-container">
          <div className="upload-form">
            <div className="form-header">
              <h4>Upload Event Photo</h4>
              <button
                className="close-btn"
                onClick={() => {
                  setShowUploadForm(false);
                  setSelectedFile(null);
                  setDescription('');
                }}
              >
                <FiX size={20} />
              </button>
            </div>

            <form onSubmit={handleUploadImage}>
              <div className="form-group">
                <label>Select Image *</label>
                <div className="file-input-wrapper">
                  <input
                    type="file"
                    id="image-input"
                    accept="image/*"
                    onChange={handleFileSelect}
                    disabled={uploading}
                  />
                  <label htmlFor="image-input" className="file-label">
                    {selectedFile ? (
                      <>
                        <FiImage size={24} />
                        <span>{selectedFile.name}</span>
                      </>
                    ) : (
                      <>
                        <FiUpload size={24} />
                        <span>Click to select image or drag & drop</span>
                      </>
                    )}
                  </label>
                </div>
              </div>

              <div className="form-group">
                <label htmlFor="description">Description (Optional)</label>
                <textarea
                  id="description"
                  value={description}
                  onChange={(e) => setDescription(e.target.value)}
                  placeholder="Add photo description or caption..."
                  rows={3}
                  disabled={uploading}
                />
              </div>

              <div className="form-actions">
                <button
                  type="button"
                  className="btn-cancel"
                  onClick={() => {
                    setShowUploadForm(false);
                    setSelectedFile(null);
                    setDescription('');
                  }}
                  disabled={uploading}
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  className="btn-upload-submit"
                  disabled={uploading || !selectedFile}
                >
                  {uploading ? 'Uploading...' : 'Upload Image'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Images Gallery */}
      {loading ? (
        <p className="gallery-loading">Loading images...</p>
      ) : images.length > 0 ? (
        <div className="images-grid">
          {images.map(image => (
            <div key={image._id} className="image-card">
              <div className="image-container">
                <img
                  src={image.imageUrl || image.photo}
                  alt={image.description}
                />
                <div className="image-overlay">
                  <button
                    className="btn-delete-image"
                    onClick={() => handleDeleteImage(image._id)}
                    title="Delete image"
                  >
                    <FiTrash2 size={18} />
                    Delete
                  </button>
                </div>
              </div>
              {image.description && (
                <p className="image-description">{image.description}</p>
              )}
            </div>
          ))}
        </div>
      ) : (
        <div className="no-images">
          <FiImage size={48} />
          <p>No photos uploaded yet</p>
          <p className="hint">Upload photos to create event memories!</p>
        </div>
      )}
    </div>
  );
};

export default PastEventImageUpload;
